import csv, json, os, re, time, urllib.request, urllib.error
from datetime import datetime, timezone
raw = os.environ["BLAND_API_KEY"].strip()
if raw.startswith("{"):
    p = json.loads(raw); raw = next((p[k] for k in ("api_key", "key", "value") if p.get(k)), raw)
gw = os.environ["GW_TOKEN"].strip()
if not gw.lower().startswith("bearer"):
    gw = "Bearer " + gw
AGENT = "+15095611012"
CSV = "/mnt/d_drive/repos/mott/recall/test list.csv"
END = datetime.now(timezone.utc).replace(hour=23, minute=59, second=0)
BANNED = re.compile(r"one moment|let me check|checking availability|please hold|give me a (?:moment|second)", re.I)

def bland(path):
    req = urllib.request.Request("https://api.bland.ai" + path, headers={"Authorization": raw, "User-Agent": "mybcat-cli"})
    with urllib.request.urlopen(req, timeout=90) as r:
        return json.loads(r.read().decode())

def gwcall(path, payload):
    req = urllib.request.Request("https://mott-booking-gw.mail.mybcat.com" + path, data=json.dumps(payload).encode(), method="POST", headers={"Content-Type": "application/json", "Authorization": gw, "User-Agent": "mybcat-cli"})
    try:
        with urllib.request.urlopen(req, timeout=90) as r:
            return r.status, json.loads(r.read().decode() or "{}")
    except urllib.error.HTTPError as e:
        return e.code, str(e.read())[:120]

pilot = {}
for r in csv.DictReader(open(CSV, encoding="utf-8-sig")):
    cell = re.sub(r"\D", "", str(r.get("MOBILE_PHONE", "")))
    if len(cell) == 11 and cell.startswith("1"):
        cell = cell[1:]
    pid = re.sub(r"\D", "", str(r.get("PATIENT_ID", "")))
    if len(cell) == 10 and pid:
        pilot[cell] = pid
print("PILOT_LOADED n=%d" % len(pilot))
state = {}
booked_seen = set()
cycle = 0
while datetime.now(timezone.utc) < END:
    cycle += 1
    try:
        listing = bland("/v1/sms/conversations?limit=100")
        rows = listing if isinstance(listing, list) else (listing.get("data") or listing.get("conversations") or [])
        active = replied = booked = stopped = 0
        for c in rows:
            if not isinstance(c, dict) or str(c.get("agent_number", "")) != AGENT:
                continue
            un = re.sub(r"\D", "", str(c.get("user_number", "")))
            if len(un) == 11 and un.startswith("1"):
                un = un[1:]
            if un not in pilot:
                continue
            cid = str(c.get("conversation_id", c.get("id", "")))
            active += 1
            prev = state.get(cid, {"msgs": 0, "node": None})
            node = str(c.get("current_node_id"))
            try:
                det = bland("/v1/sms/conversations/%s" % cid)
                d = det.get("data") if isinstance(det.get("data"), dict) else det
                msgs = d.get("messages") or []
                node = str(d.get("current_node_id"))
            except Exception as e:
                print("WARN detail fetch ...%s: %s" % (cid[-6:], str(e)[:80]))
                continue
            user_n = sum(1 for m in msgs if isinstance(m, dict) and m.get("sender") != "AGENT")
            if user_n:
                replied += 1
            fails = [m for m in msgs if isinstance(m, dict) and str(m.get("status", "")).lower() in ("failed", "undelivered")]
            if len(msgs) != prev["msgs"] or node != prev["node"]:
                last = msgs[-1] if msgs else {}
                print("EVENT conv=...%s cell=***%s node=%s msgs=%d last_from=%s" % (cid[-6:], un[-4:], node, len(msgs), (last.get("sender", "?") if isinstance(last, dict) else "?")))
            for m in msgs:
                if isinstance(m, dict) and m.get("sender") == "AGENT" and BANNED.search(str(m.get("message", ""))):
                    print("ALERT FILLER conv=...%s" % cid[-6:])
            if fails:
                print("ALERT DELIVERY_FAIL conv=...%s n=%d" % (cid[-6:], len(fails)))
            if node in ("n_suppress_stop", "n_suppress_not_me"):
                stopped += 1
                if prev["node"] != node:
                    print("ALERT OPTOUT conv=...%s node=%s" % (cid[-6:], node))
            if node in ("n_post_booking", "e_booked", "e_booked_recovered"):
                booked += 1
                if cid not in booked_seen:
                    booked_seen.add(cid)
                    s, b = gwcall("/appt-list", {"patient_id": pilot[un], "store": "711"})
                    ap = ((b.get("result") or {}).get("appointments") or []) if isinstance(b, dict) else []
                    starts = [a.get("start") for a in ap]
                    print("BOOKED conv=...%s pid=***%s gw_count=%d starts=%s" % (cid[-6:], pilot[un][-4:], len(ap), starts))
            state[cid] = {"msgs": len(msgs), "node": node}
        print("CYCLE %d %s active=%d replied=%d booked=%d stopped=%d" % (cycle, datetime.now(timezone.utc).strftime("%H:%M"), active, replied, booked, stopped))
    except Exception as e:
        print("WARN cycle %d error: %s" % (cycle, str(e)[:120]))
    time.sleep(120)
print("MONITOR_END cycles=%d" % cycle)
